"""DAG runner for the mini data harness."""

from __future__ import annotations

import csv
import json
import re
from pathlib import Path
from typing import Any, Callable


class HarnessError(Exception):
    """Raised when the harness cannot complete the DAG."""


REPO_ROOT = Path(__file__).resolve().parents[1]
MAX_RETRIES = 2


def run_dag(sources: list[str] | tuple[str, ...], output: str) -> dict[str, Any]:
    """Run extract, clean, and report stages and write a JSON report."""

    logs: list[dict[str, Any]] = []
    retry_count = 0

    def run_stage(name: str, func: Callable[[], Any]) -> Any:
        nonlocal retry_count
        for attempt in range(1, MAX_RETRIES + 2):
            try:
                result = func()
            except Exception as exc:  # noqa: BLE001 - convert all stage failures.
                logs.append(
                    {
                        "attempt": attempt,
                        "stage": name,
                        "status": "failed",
                        "error": str(exc),
                    }
                )
                if attempt > MAX_RETRIES:
                    raise HarnessError(f"{name} failed after {attempt} attempts") from exc
                retry_count += 1
            else:
                logs.append({"attempt": attempt, "stage": name, "status": "ok"})
                return result
        raise HarnessError(f"{name} failed")

    source_paths = [_repo_path(source) for source in sources]
    records = run_stage("extract", lambda: _extract(source_paths))
    cleaned, rejects = run_stage("clean", lambda: _clean(records))
    report = run_stage(
        "report",
        lambda: _build_report(cleaned, rejects, retry_count, source_paths, logs),
    )

    output_path = _repo_path(output)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(
        json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    return report


def _repo_path(path: str) -> Path:
    candidate = Path(path)
    resolved = candidate.resolve() if candidate.is_absolute() else (REPO_ROOT / candidate).resolve()
    try:
        resolved.relative_to(REPO_ROOT)
    except ValueError as exc:
        raise HarnessError(f"path is outside repo root: {path}") from exc
    return resolved


def _extract(paths: list[Path]) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for path in paths:
        if not path.exists():
            raise HarnessError(f"source does not exist: {_display_path(path)}")
        suffix = path.suffix.lower()
        if suffix == ".csv":
            records.extend(_read_csv(path))
        elif suffix == ".jsonl":
            records.extend(_read_jsonl(path))
        else:
            raise HarnessError(f"unsupported source type: {_display_path(path)}")
    return records


def _read_csv(path: Path) -> list[dict[str, Any]]:
    with path.open("r", encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle)
        return [
            dict(row)
            for row in reader
            if row and any((value or "").strip() for value in row.values())
        ]


def _read_jsonl(path: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    with path.open("r", encoding="utf-8") as handle:
        for line_number, line in enumerate(handle, start=1):
            if not line.strip():
                continue
            try:
                value = json.loads(line)
            except json.JSONDecodeError as exc:
                raise HarnessError(
                    f"invalid JSONL at {_display_path(path)}:{line_number}"
                ) from exc
            if not isinstance(value, dict):
                raise HarnessError(
                    f"JSONL record must be an object at {_display_path(path)}:{line_number}"
                )
            records.append(value)
    return records


def _clean(records: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    cleaned: list[dict[str, Any]] = []
    rejects: list[dict[str, Any]] = []
    for record in records:
        normalized = {_snake_case(str(key)): value for key, value in record.items()}
        if not str(normalized.get("id", "")).strip():
            rejects.append(normalized)
        else:
            cleaned.append(normalized)
    return cleaned, rejects


def _build_report(
    cleaned: list[dict[str, Any]],
    rejects: list[dict[str, Any]],
    retry_count: int,
    source_paths: list[Path],
    logs: list[dict[str, Any]],
) -> dict[str, Any]:
    return {
        "processed_count": len(cleaned),
        "rejected_count": len(rejects),
        "retry_count": retry_count,
        "source_files": [_display_path(path) for path in source_paths],
        "records": cleaned,
        "rejects": rejects,
        "logs": logs,
        "memory_reference": "memory/memory_summary.md",
    }


def _snake_case(value: str) -> str:
    value = value.strip()
    value = re.sub(r"(.)([A-Z][a-z]+)", r"\1_\2", value)
    value = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", value)
    value = re.sub(r"[^0-9A-Za-z]+", "_", value)
    return value.strip("_").lower()


def _display_path(path: Path) -> str:
    return path.resolve().relative_to(REPO_ROOT).as_posix()

import json

from mini_harness.runner import HarnessError, run_dag


def test_run_dag_writes_report():
    output = "tmp/test-report.json"

    output_path = run_dag.__globals__["REPO_ROOT"] / output
    try:
        report = run_dag(["data/input.csv", "data/events.jsonl"], output)

        assert report["processed_count"] == 4
        assert report["rejected_count"] == 2
        assert report["retry_count"] == 0
        assert report["source_files"] == ["data/input.csv", "data/events.jsonl"]
        assert report["records"][0] == {"id": "1", "user_name": "Alice", "score": "10"}
        assert report["memory_reference"] == "memory/memory_summary.md"
        assert {entry["stage"] for entry in report["logs"]} == {
            "extract",
            "clean",
            "report",
        }
        assert all(
            {"attempt", "stage", "status"}.issubset(entry) for entry in report["logs"]
        )

        written = json.loads(output_path.read_text())
        assert written["processed_count"] == 4
    finally:
        output_path.unlink(missing_ok=True)


def test_run_dag_rejects_outside_output_path():
    try:
        run_dag(["data/input.csv"], "../outside.json")
    except HarnessError as exc:
        assert "outside repo root" in str(exc)
    else:
        raise AssertionError("expected HarnessError")
